// ====== CẤU HÌNH – sửa ở đây ======
// Token Threads và key Gemini nằm trong Credentials của n8n, KHÔNG để ở đây.
const SITE_URL = 'https://toeicmastery.click';
const SCREENSHOT_SERVICE = 'http://localhost:3001';

// Tính năng để khoe. "facts" là sự thật về tính năng – AI chỉ được nói trong phạm vi này.
// pro: true = tính năng của gói Pro, bài viết phải ghi rõ là Pro.
const FEATURES = [
  { path: '/vocabulary', name: 'Từ vựng TOEIC 20 ngày', pro: false,
    facts: 'Lộ trình từ vựng TOEIC 20 ngày, 312 từ; học theo lộ trình, theo band điểm hoặc theo cụm từ cố định; flashcard; ôn theo phương pháp lặp lại ngắt quãng (spaced repetition), web nhắc ôn đúng lúc để nhớ lâu.' },
  { path: '/practice', name: 'Kho đề luyện thi', pro: false,
    facts: 'Kho đề TOEIC bám sát cấu trúc đề thật: bộ ETS 2023 (10 đề), bộ Mastery ETS 2026 (10 đề), lọc theo Full Test, Listening, Reading hoặc từng Part, lọc theo độ khó.' },
  { path: '/listening', name: 'Luyện Listening từng Part', pro: false,
    facts: 'Luyện nghe theo từng Part 1–4 (mỗi Part 31 đề luyện tập). Gói Pro có thêm Transcript Mastery ETS 2026: nghe chép chính tả trọn bộ ETS 2026 Part 1–4, nghe lại từng câu, gợi ý chữ cái, chấm ngay từng câu, kèm dịch song ngữ và đáp án.' },
  { path: '/grammar', name: 'Ngữ pháp TOEIC', pro: false,
    facts: 'Lý thuyết, ví dụ và bài luyện tập cho từng chủ điểm ngữ pháp TOEIC (ví dụ Đại từ có 86 câu luyện tập). Có phần Mastery luyện chuyên sâu Ngữ pháp & Từ vựng Part 5–6 (danh từ, động từ, tính từ, trạng từ, giới từ): 32 bài học, 1065 câu luyện tập.' },
  // Thêm lại khi tài khoản demo có từ đã lưu (trang đang trống):
  // { path: '/dictionary', name: 'Từ điển thông minh', pro: false,
  //   facts: 'Tra nghĩa, phát âm, ví dụ, hoặc bôi đen bất kỳ từ nào trên trang để tra nhanh; lưu từ để ôn lại. Tra từ bôi đen không giới hạn là của gói Pro.' },
];

// Câu comment gắn link (code chọn, không để AI viết, để link luôn đúng).
const LINK_REPLIES = [
  'ngay đây thôi, gửi ae link học cho tiện nè 👉 ' + SITE_URL,
  'link đây nha, đăng ký tài khoản là vô học được liền 👉 ' + SITE_URL,
  'ai hỏi link thì đây nè 👇\n' + SITE_URL,
  'web đây ae ơi, lưu lại kẻo trôi 👉 ' + SITE_URL,
];

// Tên thương hiệu khác: bài nào nhắc tới sẽ KHÔNG được đăng.
const BLOCKED_BRANDS = [
  'study4', 'prep\\.vn', 'dethitoeic', 'hochay', 'toeichanquoc', 'toeic hàn quốc', 'english mastery',
  'mshoa', 'ms hoa', '\\bzim\\b', 'ielts fighter', 'tienganh123', 'elsa speak', 'duolingo',
  'vocamax', 'ontoeic', 'openquiz', 'toeicmastery\\.vn',
];

const pick = (a) => a[Math.floor(Math.random() * a.length)];
const store = $getWorkflowStaticData('global');
const recent = store.recentFeatures || [];
const pool = FEATURES.filter((f) => !recent.includes(f.path));
const feature = pick(pool.length ? pool : FEATURES);

return [{
  json: { SITE_URL, SCREENSHOT_SERVICE, feature, linkReply: pick(LINK_REPLIES), BLOCKED_BRANDS, timestamp: new Date().toISOString() },
}];

// Bài không đạt -> báo lỗi và DỪNG, không đăng gì.
const prev = $('🧹 Tạo prompt').first().json;
const resp = $input.first().json;

let post = (resp.candidates?.[0]?.content?.parts || []).filter((p) => !p.thought).map((p) => p.text || '').join('').trim();
post = post.replace(/\*\*/g, '').replace(/^["“]|["”]$/g, '').trim();

const problems = [];
if (!post) problems.push('AI không trả về nội dung (finishReason: ' + (resp.candidates?.[0]?.finishReason || 'n/a') + ')');
if (post.length > 500) problems.push('Dài ' + post.length + ' ký tự (Threads giới hạn 500)');
const lower = post.toLowerCase();
for (const brand of prev.BLOCKED_BRANDS) {
  if (new RegExp(brand, 'i').test(lower)) problems.push('Nhắc thương hiệu bị chặn: ' + brand);
}
if (/https?:\/\/|\b[a-z0-9-]+\.(vn|com|net|org|io|app|click|me|co)\b/.test(lower)) problems.push('Bài có link/tên miền (link chỉ để ở comment)');
if (/\bfree\b|miễn phí|0đ|0 đồng|không mất tiền/.test(lower)) problems.push('Nói "free/miễn phí" – không đúng với các tính năng Pro');
if (/không cần (đăng nhập|đăng ký|tài khoản)/.test(lower)) problems.push('Nói "không cần đăng nhập" – web phải đăng nhập');
if (/tăng\s*\d+\s*điểm|cam kết/.test(lower)) problems.push('Có cam kết/hứa tăng điểm');
if (prev.feature.pro && !/\bpro\b/.test(lower)) problems.push('Tính năng Pro nhưng bài không ghi rõ "Pro"');

if (problems.length > 0) {
  throw new Error('Bài KHÔNG được đăng:\n- ' + problems.join('\n- ') + '\n\nNội dung AI viết:\n' + post);
}
return [{ json: { ...prev, generatedContent: post } }];

const prev = $('✅ Kiểm tra bài').first().json;
const store = $getWorkflowStaticData('global');
// Nhớ 3 tính năng vừa khoe để lần sau đổi chủ đề.
store.recentFeatures = [prev.feature.path, ...(store.recentFeatures || []).filter((p) => p !== prev.feature.path)].slice(0, 3);
return [{
  json: {
    status: 'ĐÃ ĐĂNG LÊN THREADS (kèm ảnh + comment link)',
    thoiGian: new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' }),
    tinhNang: prev.feature.name,
    noiDung: prev.generatedContent,
    commentLink: prev.linkReply,
    postId: $('🚀 Publish bài').first().json.id,
    replyId: $input.first().json.id,
  },
}];
